window.docContents[140].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Fewer-irreducible-representations-when-___G___-___-0-in-k/#Chapter4___Exercise4___2___3":{"contents":"Exercise 4.2.3. Show that if |G| = 0 in k, then the number of isomorphism classes of irreducible representations of G over k is strictly less than the number of conjugacy classes in G.\n\nHint: Let P = \\sum_{g \\in G} g \\in k[G]. Then P^2 = 0. So P has zero trace in every finite dimensional representation of G over k.\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.2. Characters\tFewer irreducible representations when |G| = 0 in k","header":"Fewer irreducible representations when |G| = 0 in k","id":"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Fewer-irreducible-representations-when-___G___-___-0-in-k/#Chapter4___Exercise4___2___3"},"/5___-Representations-of-finite-groups___-Further-results/5___7___-Virtual-representations/Virtual-representation-and-its-character/#Chapter5___Definition5___7___1":{"contents":"Definition 5.7.1. A virtual representation of a finite group G is an integer linear combination of irreducible representations of G, V = \\sum n_i V_i, n_i \\in \\mathbb{Z} (i.e., n_i are not assumed to be nonnegative). The character of V is \\chi_V := \\sum n_i \\chi_{V_i}.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.7. Virtual representations\tVirtual representation and its character","header":"Virtual representation and its character","id":"/5___-Representations-of-finite-groups___-Further-results/5___7___-Virtual-representations/Virtual-representation-and-its-character/#Chapter5___Definition5___7___1"}});
